USE [IAM_LocalTest];
GO
SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET CONCAT_NULL_YIELDS_NULL ON; SET ARITHABORT ON; SET NUMERIC_ROUNDABORT OFF; SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'IAM_LocalTest' THROW 51000, 'Wrong database selected.', 1;
BEGIN TRANSACTION;
DECLARE @OrganizationId bigint = (SELECT OrganizationId FROM [Identity].[OrganizationUnit] WHERE UnitType=N'Organization' AND UnitName=N'AMS Test Organization' AND IsActive=1);
DECLARE @CountryId bigint = (SELECT OrganizationUnitId FROM [Identity].[OrganizationUnit] WHERE OrganizationId=@OrganizationId AND UnitType=N'Country' AND UnitName=N'India' AND IsActive=1);
IF @OrganizationId IS NULL OR @CountryId IS NULL THROW 51001, 'AMS Test Organization / India was not found.', 1;
DECLARE @Regions TABLE(Name nvarchar(400), Code nvarchar(100));
INSERT @Regions VALUES (N'East Test Region', N'REG-TEST-01');
INSERT @Regions VALUES (N'North Test Region', N'REG-TEST-02');
INSERT @Regions VALUES (N'South Test Region', N'REG-TEST-03');
INSERT @Regions VALUES (N'West Test Region', N'REG-TEST-04');
DELETE FROM @Regions WHERE Name=N'South Test Region';
INSERT INTO [Identity].[OrganizationUnit](OrganizationId,ParentOrganizationUnitId,UnitType,UnitCode,UnitName,IsActive,CreatedAt,UpdatedAt) SELECT @OrganizationId,@CountryId,N'Region',r.Code,r.Name,1,SYSUTCDATETIME(),SYSUTCDATETIME() FROM @Regions r WHERE NOT EXISTS(SELECT 1 FROM [Identity].[OrganizationUnit] u WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'Region' AND u.UnitName=r.Name);
UPDATE u SET HierarchyPath=p.HierarchyPath+CONVERT(nvarchar(20),u.OrganizationUnitId)+N'/' FROM [Identity].[OrganizationUnit] u JOIN [Identity].[OrganizationUnit] p ON p.OrganizationUnitId=u.ParentOrganizationUnitId WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'Region' AND u.HierarchyPath IS NULL;
DECLARE @States TABLE(Name nvarchar(400), RegionName nvarchar(400), Code nvarchar(100));
INSERT @States VALUES (N'Telangana',N'South Test Region',N'ST-TEST-01');
