INSERT INTO [Identity].[OrganizationUnit](OrganizationId,ParentOrganizationUnitId,UnitType,UnitCode,UnitName,IsActive,CreatedAt,UpdatedAt) SELECT @OrganizationId,r.OrganizationUnitId,N'State',s.Code,s.Name,1,SYSUTCDATETIME(),SYSUTCDATETIME() FROM @States s JOIN [Identity].[OrganizationUnit] r ON r.OrganizationId=@OrganizationId AND r.UnitType=N'Region' AND r.UnitName=s.RegionName WHERE NOT EXISTS(SELECT 1 FROM [Identity].[OrganizationUnit] u WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'State' AND u.UnitName=s.Name);
UPDATE u SET HierarchyPath=p.HierarchyPath+CONVERT(nvarchar(20),u.OrganizationUnitId)+N'/' FROM [Identity].[OrganizationUnit] u JOIN [Identity].[OrganizationUnit] p ON p.OrganizationUnitId=u.ParentOrganizationUnitId WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'State' AND u.HierarchyPath IS NULL;
