INSERT INTO [Identity].[OrganizationUnit](OrganizationId,ParentOrganizationUnitId,UnitType,UnitCode,UnitName,IsActive,CreatedAt,UpdatedAt) SELECT @OrganizationId,s.OrganizationUnitId,N'Branch',b.Code,b.Name,1,SYSUTCDATETIME(),SYSUTCDATETIME() FROM @Branches b JOIN [Identity].[OrganizationUnit] s ON s.OrganizationId=@OrganizationId AND s.UnitType=N'State' AND s.UnitName=b.StateName WHERE NOT EXISTS(SELECT 1 FROM [Identity].[OrganizationUnit] u WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'Branch' AND u.ParentOrganizationUnitId=s.OrganizationUnitId AND u.UnitName=b.Name);
UPDATE u SET HierarchyPath=p.HierarchyPath+CONVERT(nvarchar(20),u.OrganizationUnitId)+N'/' FROM [Identity].[OrganizationUnit] u JOIN [Identity].[OrganizationUnit] p ON p.OrganizationUnitId=u.ParentOrganizationUnitId WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'Branch' AND u.HierarchyPath IS NULL;
