INSERT INTO [Identity].[OrganizationUnit](OrganizationId,ParentOrganizationUnitId,UnitType,UnitCode,UnitName,IsActive,CreatedAt,UpdatedAt) SELECT @OrganizationId,b.OrganizationUnitId,N'Location',l.Code,l.Name,1,SYSUTCDATETIME(),SYSUTCDATETIME() FROM @Locations l JOIN [Identity].[OrganizationUnit] b ON b.OrganizationId=@OrganizationId AND b.UnitType=N'Branch' AND b.UnitName=l.BranchName WHERE NOT EXISTS(SELECT 1 FROM [Identity].[OrganizationUnit] u WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'Location' AND u.ParentOrganizationUnitId=b.OrganizationUnitId AND u.UnitName=l.Name);
UPDATE u SET HierarchyPath=p.HierarchyPath+CONVERT(nvarchar(20),u.OrganizationUnitId)+N'/' FROM [Identity].[OrganizationUnit] u JOIN [Identity].[OrganizationUnit] p ON p.OrganizationUnitId=u.ParentOrganizationUnitId WHERE u.OrganizationId=@OrganizationId AND u.UnitType=N'Location' AND u.HierarchyPath IS NULL;
IF EXISTS(SELECT 1 FROM @Branches b LEFT JOIN [Identity].[OrganizationUnit] u ON u.OrganizationId=@OrganizationId AND u.UnitType=N'Branch' AND u.UnitName=b.Name WHERE u.OrganizationUnitId IS NULL) THROW 51002, 'Branch verification failed.', 1;
IF EXISTS(SELECT 1 FROM @Locations l JOIN [Identity].[OrganizationUnit] b ON b.OrganizationId=@OrganizationId AND b.UnitType=N'Branch' AND b.UnitName=l.BranchName LEFT JOIN [Identity].[OrganizationUnit] u ON u.OrganizationId=@OrganizationId AND u.UnitType=N'Location' AND u.ParentOrganizationUnitId=b.OrganizationUnitId AND u.UnitName=l.Name WHERE u.OrganizationUnitId IS NULL) THROW 51003, 'Location verification failed.', 1;
COMMIT;
SELECT UnitType,COUNT(*) AS ActiveCount FROM [Identity].[OrganizationUnit] WHERE OrganizationId=@OrganizationId AND IsActive=1 GROUP BY UnitType ORDER BY UnitType;
SELECT s.UnitName AS StateName,b.UnitName AS BranchName,COUNT(l.OrganizationUnitId) AS LocationCount FROM [Identity].[OrganizationUnit] b JOIN [Identity].[OrganizationUnit] s ON s.OrganizationUnitId=b.ParentOrganizationUnitId LEFT JOIN [Identity].[OrganizationUnit] l ON l.ParentOrganizationUnitId=b.OrganizationUnitId AND l.UnitType=N'Location' AND l.IsActive=1 WHERE b.OrganizationId=@OrganizationId AND b.UnitType=N'Branch' AND b.UnitName IN (SELECT Name FROM @Branches) GROUP BY s.UnitName,b.UnitName ORDER BY s.UnitName,b.UnitName;
